<template>
  <div class="space-y-6">
    <div class="flex items-center justify-between">
      <h2 class="text-xl font-bold text-ink-gray-9">Benches</h2>
      <Button variant="solid" @click="showCreateModal = true">
        New Bench
      </Button>
    </div>

    <!-- Bench List -->
    <div class="grid grid-cols-1 gap-6 lg:grid-cols-2 xl:grid-cols-3">
      <BenchCard
        v-for="bench in benches.data"
        :key="bench.name"
        :bench="bench"
        @restart="handleRestart"
        @viewLogs="handleViewLogs"
      />
      <div v-if="!benches.data?.length && !benches.loading" class="col-span-full py-20 text-center border-2 border-dashed rounded-xl">
        <Terminal class="mx-auto h-12 w-12 text-ink-gray-3" />
        <h3 class="mt-4 text-sm font-semibold text-ink-gray-9">No benches found</h3>
        <p class="mt-1 text-sm text-ink-gray-5">Get started by creating your first bench.</p>
      </div>
    </div>

    <BenchLogModal
      v-if="selectedBench"
      v-model="showLogModal"
      :bench="selectedBench"
    />

    <CreateBenchModal
      v-model="showCreateModal"
      @created="benches.reload()"
    />
  </div>
</template>

<script setup>
import BenchCard from "@/components/benches/BenchCard.vue"
import BenchLogModal from "@/components/benches/BenchLogModal.vue"
import CreateBenchModal from "@/components/benches/CreateBenchModal.vue"
import { createResource } from "frappe-ui"
import { Terminal } from "lucide-vue-next"
import { ref } from "vue"

const showCreateModal = ref(false)
const showLogModal = ref(false)
const selectedBench = ref(null)

const benches = createResource({
	url: "htbencher.api.get_benches",
	auto: true,
})

function handleRestart(bench) {
	// Implementation for restart
	console.log("Restarting bench:", bench.name)
}

function handleViewLogs(bench) {
	selectedBench.value = bench
	showLogModal.value = true
}
</script>
